122	    unclosedTags = [];
123	  }
124	  if (!unclosableTags) {
125	    unclosableTags = [];
126	  }
127	
128	  mainLoop: for (const child of children) {
129	    for (const transformer of textMatchTransformers) {
130	      if (!transformer.export) {
131	        continue;
132	      }
133	
134	      const result = transformer.export(
135	        child,
136	        (parentNode) =>
137	          exportChildren(
138	            parentNode,
139	            textTransformersIndex,
140	            textMatchTransformers,
141	            unclosedTags,
142	            // Add current unclosed tags to the list of unclosable tags - we don't want nested tags from
143	            // textmatch transformers to close the outer ones, as that may result in invalid markdown.
144	            // E.g. **text [text**](https://lexical.io)
145	            // is invalid markdown, as the closing ** is inside the link.
146	            //
147	            [...unclosableTags, ...unclosedTags],
148	          ),
149	        (textNode, textContent) =>
150	          exportTextFormat(
151	            textNode,
152	            textContent,
153	            textTransformersIndex,
154	            unclosedTags,
155	            unclosableTags,
156	          ),
157	      );
158	
159	      if (result != null) {
160	        output.push(result);
161	        continue mainLoop;
162	      }
163	    }
164	
165	    if ($isLineBreakNode(child)) {
166	      output.push('\n');
167	    } else if ($isTextNode(child)) {
168	      output.push(
169	        exportTextFormat(
170	          child,
171	          child.getTextContent(),
172	          textTransformersIndex,
173	          unclosedTags,
174	          unclosableTags,
175	        ),
176	      );
177	    } else if ($isElementNode(child)) {
178	      // empty paragraph returns ""
179	      output.push(
180	        exportChildren(
181	          child,
182	          textTransformersIndex,
183	          textMatchTransformers,
184	          unclosedTags,
185	          unclosableTags,
186	        ),
187	      );
188	    } else if ($isDecoratorNode(child)) {
189	      output.push(child.getTextContent());
190	    }
191	  }
192	
193	  return output.join('');
194	}
